import { test } from 'node:test';
import assert from 'node:assert/strict';
import { total, itemCount } from '../src/cart.js';

test('total without discount', () => {
  assert.equal(total([{ price: 100, qty: 2 }, { price: 50, qty: 1 }]), 250);
});

// Issue #12: the customer's discount applies once.
test('total applies the customer discount once', () => {
  assert.equal(total([{ price: 1000, qty: 1 }], 0.1), 900);
});

// Each line is 1,000, so n lines give a subtotal of n * 1,000.
const lines = (n) => Array.from({ length: n }, () => ({ price: 1000, qty: 1 }));

test('total applies the bulk discount once, after the customer discount, at 10 lines', () => {
  assert.equal(total(lines(10), 0.1), 8550);
});

test('total applies only the bulk discount at 10 lines when the rate is 0', () => {
  assert.equal(total(lines(10), 0), 9500);
});

test('total applies no bulk discount at 9 lines', () => {
  assert.equal(total(lines(9), 0.1), 8100);
});

test('item count', () => {
  assert.equal(itemCount([{ price: 1, qty: 3 }, { price: 1, qty: 2 }]), 5);
});
